// Sky touch keyboard: custom layouts and sizes for GNOME Shell's own on-screen keyboard (GNOME Shell 48).
// The layouts are JSON files (layouts/*.json, generated by tools/gen-sky-osk-layouts.py), compiled into sky-osk-layouts.gresource.
// Portrait monitor -> layout "sky" (ortholinear 10 x 5, Esc/Tab/arrows strip); landscape monitor -> "sky-split" (Planck-style 6 + 6 halves, each flush to its
// screen edge; the middle is transparent and click-through: on Wayland the shell only picks reactive actors, so the containers are made non-reactive
// in split mode and only the keys take touches).
// Everything else (digits/phone/email/url keyboards, terminal layout, other input sources, emoji, popups, text-input handling) stays GNOME's.
import Gio from 'gi://Gio';
import GLib from 'gi://GLib';
import Clutter from 'gi://Clutter';

import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import {Keyboard} from 'resource:///org/gnome/shell/ui/keyboard.js';

// keyboard height as a fraction of the monitor height (logical pixels); config.json next to this file overrides it
// (read when the extension is enabled, so `gnome-extensions disable/enable` applies a change without a new login)
const DEFAULTS = {portraitHeight: 0.34, landscapeHeight: 0.50};

// purposes that keep GNOME's own special layouts
const KEEP_PURPOSES = [
    Clutter.InputContentPurpose.DIGITS,
    Clutter.InputContentPurpose.NUMBER,
    Clutter.InputContentPurpose.PHONE,
    Clutter.InputContentPurpose.EMAIL,
    Clutter.InputContentPurpose.URL,
    Clutter.InputContentPurpose.TERMINAL,
];

// invisible, inert filler keys: they commit a zero-width space (see tools/gen-sky-osk-layouts.py, SPACER) and only keep the grid columns alive
// every other key's container (key + its padding) takes touches, so a tap between two keys never falls through to the app below
// (which would drop the text focus and close the keyboard); only the spacer area, the middle gap, stays click-through
function hideSpacers(keyboard) {
    for (const layer of Object.values(keyboard._layers ?? {})) {
        for (const key of layer.get_children()) {
            if (key.keyButton?.get_label?.() === '\u200b') {
                key.opacity = 0;
                key.reactive = false;
                key.keyButton.reactive = false;
                key.keyButton.can_focus = false;
            } else if (key.keyButton) {
                key.reactive = true;
            }
        }
    }
}

// split mode: no background, no touch capture outside the keys (the gap lets touches through to the windows below)
function applyMode(keyboard, split) {
    keyboard._skySplit = split;
    if (split)
        keyboard.add_style_class_name('sky-split');
    else
        keyboard.remove_style_class_name('sky-split');
    keyboard.reactive = !split;
    Main.layoutManager.keyboardBox.reactive = !split;
}

function isLandscape() {
    const monitor = Main.layoutManager.keyboardMonitor;
    return !!monitor && monitor.width > monitor.height;
}

export default class SkyOsk extends Extension {
    enable() {
        let cfg = {...DEFAULTS};
        try {
            const [, bytes] = Gio.File.new_for_path(GLib.build_filenamev([this.path, 'config.json'])).load_contents(null);
            cfg = {...cfg, ...JSON.parse(new TextDecoder().decode(bytes))};
        } catch (e) {
            // no config file: defaults
        }
        this._resource = Gio.Resource.load(GLib.build_filenamev([this.path, 'sky-osk-layouts.gresource']));
        Gio.resources_register(this._resource);

        const proto = Keyboard.prototype;
        this._origRelayout = proto._relayout;
        this._origUpdateLayout = proto._updateLayout;
        this._origSetActiveLevel = proto._setActiveLevel;
        const origUpdateLayout = this._origUpdateLayout;
        const origSetActiveLevel = this._origSetActiveLevel;

        // split: the key grid fills the whole width (halves flush to the screen edges) instead of being centred at its aspect ratio
        proto._setActiveLevel = function (level) {
            origSetActiveLevel.call(this, level);
            if (this._skySplit && this._currentPage)
                this._aspectContainer.setRatio(1e6, 1);
        };

        proto._relayout = function () {
            const monitor = Main.layoutManager.keyboardMonitor;
            if (!monitor)
                return;
            this.width = monitor.width;
            this.height = monitor.height * (monitor.width > monitor.height ? cfg.landscapeHeight : cfg.portraitHeight);
        };

        proto._updateLayout = function (groupName, purpose) {
            this._skyLandscape = isLandscape();
            if (groupName === 'us' && !KEEP_PURPOSES.includes(purpose))
                groupName = this._skyLandscape ? 'sky-split' : 'sky';
            const ret = origUpdateLayout.call(this, groupName, purpose);
            hideSpacers(this);
            applyMode(this, groupName === 'sky-split');
            return ret;
        };

        this._monitorsId = Main.layoutManager.connect('monitors-changed', () => {
            // after the shell's own handler: rebuild the keys when the orientation changed
            GLib.idle_add(GLib.PRIORITY_DEFAULT_IDLE, () => {
                const kb = Main.keyboard?.keyboardActor;
                if (kb && kb._skyLandscape !== isLandscape())
                    kb._updateKeys();
                kb?._relayout();
                return GLib.SOURCE_REMOVE;
            });
        });

        this._refresh();
    }

    disable() {
        if (this._monitorsId) {
            Main.layoutManager.disconnect(this._monitorsId);
            this._monitorsId = 0;
        }
        const proto = Keyboard.prototype;
        proto._relayout = this._origRelayout;
        proto._updateLayout = this._origUpdateLayout;
        proto._setActiveLevel = this._origSetActiveLevel;
        this._origRelayout = null;
        this._origUpdateLayout = null;
        this._origSetActiveLevel = null;
        const kb = Main.keyboard?.keyboardActor;
        if (kb)
            applyMode(kb, false);
        Main.layoutManager.keyboardBox.reactive = true;
        this._refresh();
        if (this._resource) {
            Gio.resources_unregister(this._resource);
            this._resource = null;
        }
    }

    _refresh() {
        const kb = Main.keyboard?.keyboardActor;
        if (!kb)
            return;
        kb._updateKeys();
        kb._relayout();
    }
}
